using EEMS.Modules.Operations.Domain;namespace EEMS.UnitTests.Operations;public sealed class OperationsTests{[Fact]public void ReporterCannotReviewOwnIncident(){var u=Guid.NewGuid();Assert.Throws<InvalidOperationException>(()=>IncidentReview.Record(Guid.NewGuid(),Guid.NewGuid(),u,u,2,"Done"));}[Fact]public void ChecklistItemCompletesOnce(){var i=ChecklistItem.Create(Guid.NewGuid(),Guid.NewGuid(),"Verify");i.Complete(Guid.NewGuid());Assert.Throws<InvalidOperationException>(()=>i.Complete(Guid.NewGuid()));}[Fact]public void IncidentTransitionIncrementsVersion(){var i=Incident.Report(Guid.NewGuid(),Guid.NewGuid(),null,Guid.NewGuid(),null,1,1,"Issue","Description");i.MoveTo(2);Assert.Equal(2,i.Version);}}
